import{_ as a,C as r,o as n,c as o,E as i,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"企业 Agent 控制平面需要决策信封，而不只是配置优先级","description":"","frontmatter":{"title":"企业 Agent 控制平面需要决策信封，而不只是配置优先级","date":"2026-08-06","column":"industry-architecture","category":"daily","summary":"托管设置可以表达组织意图，但真正的企业 Agent 治理需要把政策来源、主体、能力、模型、沙箱和恢复上下文绑定到每次关键执行，并由各执行点返回证据收据。","item_id":"Q-20260806-02","source_research_object":"research/analysis/Q-20260806-02-enterprise-agent-control-plane.md","source_reading_result":"research/reading/Q-20260806-02-enterprise-agent-control-plane.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-06-enterprise-agent-decision-envelope-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-06-enterprise-agent-decision-envelope.md","filePath":"zh/industry/2026-08-06-enterprise-agent-decision-envelope.md","lastUpdated":1787407830000}'),s={name:"zh/industry/2026-08-06-enterprise-agent-decision-envelope.md"};function l(c,e,h,p,u,m){const t=r("ArticleCover");return n(),o("div",null,[i(t,{image:"/assets/covers/daily-2026-08-06-enterprise-agent-decision-envelope-cover-v2.jpg",kicker:"行业架构 · 每日研究",title:"企业 Agent 控制平面需要决策信封，而不只是配置优先级",summary:"托管设置可以表达组织意图，但真正的企业 Agent 治理需要把政策来源、主体、能力、模型、沙箱和恢复上下文绑定到每次关键执行，并由各执行点返回证据收据。",version:"Q-20260806-02",status:"Daily Runtime V5 · 2026-08-06",languageHref:"/en/industry/2026-08-06-enterprise-agent-decision-envelope",languageLabel:"English"}),e[0]||(e[0]=d(' # 企业 Agent 控制平面需要决策信封，而不只是配置优先级 <p>企业编码 Agent 的治理表面通常分散在托管设置、工具权限、操作系统沙箱、模型选择和会话恢复中。配置可以声明“谁的政策优先”，但不能自动证明每一条执行路径都真正应用了同一政策。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p><strong>企业 Agent 控制平面应为每次关键执行生成版本化决策信封，并要求执行点返回 enforcement receipt。</strong> 决策信封至少绑定政策来源、执行主体、请求能力、实际模型、沙箱模式和恢复上下文。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文只消费获准进入 Production 的 Research Object。其依据是同日完成的 Reading Result；Production 没有独立复现安全绕过，也没有把厂商修复说明提升为第三方验证结果。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>Research Object 把组织政策分发、权限提示、OS 沙箱、模型回退和 session resume 放在同一架构问题中。它同时保留了重要矛盾：官方文档赋予 managed settings 最高优先级，但发布说明仍报告过绕过托管禁用策略或工作流沙箱边界的执行路径。由此可见，配置权威与执行点一致性是两个不同问题。</p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制表面</th><th>表达的意图</th><th>需要的执行证据</th><th>未被现有证据证明的内容</th></tr></thead><tbody><tr><td>Managed settings</td><td>组织政策与优先级</td><td>有效政策版本和来源</td><td>所有路径都执行了同一政策</td></tr><tr><td>工具权限</td><td>某类工具是否允许</td><td>请求、决定、操作者与原因</td><td>子进程与绕行路径被完全覆盖</td></tr><tr><td>OS sandbox</td><td>Bash 与子进程的系统边界</td><td>实际沙箱模式与失败行为</td><td>跨平台等价与绝不 fail-open</td></tr><tr><td>模型回退</td><td>执行身份发生替换</td><td>原模型、实际模型、原因与属性变化</td><td>回退已被授权且语义等价</td></tr><tr><td>Session resume</td><td>继续过去工作</td><td>工作目录、政策、模型、沙箱和未结副作用清单</td><td>恢复上下文与原上下文完全等价</td></tr></tbody></table><p>每一行都区分了文档化意图、应产生的证据和当前未知项；表格不把厂商声明解释为独立验证。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>最高优先级配置是必要条件，却不是完整控制平面。Agent、Skill、workflow、命令、子进程和恢复路径都可能形成不同 enforcement point。控制平面的核心任务，是证明每个执行点应用了相同的有效政策，或在无法证明时明确 fail closed。</p><p>模型回退也不能只作为提醒。模型身份变化可能改变成本、驻留、能力和安全属性，因此回退应成为可授权的状态迁移。恢复会话同样不只是恢复聊天文本，而是恢复工作目录、政策版本、实际模型、沙箱状态和未完成影响的语义上下文。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对企业数字员工，Position 与 WorkOrder 应先解析为 effective policy snapshot；每个 Operation Node 接收决策信封，并返回包含实际执行身份和政策版本的收据。模型替换、沙箱不可用和恢复上下文漂移应进入 allow、deny 或 escalation 流程。</p><p>对 CodeFlowMu，应把政策解析投影与 FCoP 生命周期状态分开，持久化 requested/actual model、sandbox mode、permission decision 与 policy provenance，并在 resume 时比较上下文 manifest，发现实质漂移就阻断或升级。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>证据来自官方发布说明和文档，没有独立安全公告、利用复现、平台回归矩阵或事故下降数据。当前文档也可能与发布时实现状态不完全一致。本文因此只提出架构判断，不宣称命名修复已经被独立证明有效。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>需要确定哪些政策决定必须集中完成、哪些可带来源证明地缓存；哪些模型属性变化必须重新授权；如何证明所有执行路径使用同一政策版本；以及哪些恢复差异可以继续、哪些必须阻断。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图以决策信封为中心，把政策、主体与能力、模型、沙箱、恢复上下文连接到执行点收据。来源标注为基于 Research Object 的 Research Center 架构综合。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260806-02-enterprise-agent-control-plane.md" target="_blank" rel="noreferrer">Research Object</a>：本文唯一分析输入，明确区分文档化政策、执行一致性与独立验证缺口。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260806-02-enterprise-agent-control-plane.md" target="_blank" rel="noreferrer">Reading Result</a>：Research Object 声明的证据边界和来源追溯记录；本文不从该记录重新研究。</li></ol>',25))])}const _=a(s,[["render",l]]);export{b as __pageData,_ as default};
